#!/usr/bin/env node
/**
 * Deterministic small-fixture generator for external stress testing
 * (builder-10). Writes contract-format tool manifests under
 * stress/.generated/external/ until builder-4's gen-tools.mjs + builder-2's
 * make-config.mjs land; then the full-scale manifests replace these.
 *
 * Output (all under stress/.generated/external/):
 *   tools/<serverId>.json   — contract-format manifest per fixture server
 *   servers.json            — Action Hub config: servers[] (stdio fixture
 *                             servers), autoDiscover:false
 *   env.sh                  — isolation env vars for every stress run
 *
 * Usage: node stress/external/make-fixture.mjs [--servers N] [--tools-per N]
 */
import { mkdir, readFile, symlink, unlink, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "..", "..");
const outBase = resolve(here, "..", ".generated", "external");
const runStamp = new Date().toISOString().replace(/[:.]/g, "-");
const outDir = join(outBase, `run-${runStamp}`); // fresh per run — no stale reuse
const resultsDir = resolve(here, "..", ".generated", "results");

function argNum(name, fallback) {
  const i = process.argv.indexOf(name);
  return i !== -1 ? Number(process.argv[i + 1]) : fallback;
}
const serverCount = argNum("--servers", 3);
const toolsPer = argNum("--tools-per", 20);

// Deterministic PRNG (mulberry32, seeded) — contract: no Math.random.
let seed = 0x9e3779b9;
function rand() {
  seed |= 0;
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

const DOMAINS = ["crm", "billing", "inventory", "mail", "calendar", "docs", "metrics", "support"];
const QUERIES = ["show records for", "find active", "summarize recent", "export daily", "audit all"];

async function main() {
  await mkdir(join(outDir, "tools"), { recursive: true });
  await mkdir(outDir, { recursive: true });

  const serverIds = [];
  for (let s = 0; s < serverCount; s++) {
    const id = `fixture-${String(s).padStart(2, "0")}`;
    serverIds.push(id);
    const tools = [];
    for (let i = 0; i < toolsPer; i++) {
      const domain = DOMAINS[(s + i) % DOMAINS.length];
      tools.push({
        name: `${["list", "get", "find", "count", "fetch", "query"][Math.floor(rand() * 6)]}_${domain}_${String(i).padStart(3, "0")}`,
        description: `Stress fixture tool ${s}.${i}: ${QUERIES[Math.floor(rand() * QUERIES.length)]} ${domain}.`,
        inputSchema: {
          type: "object",
          properties: { q: { type: "string", description: "query text" } },
        },
        annotations: { readOnlyHint: s % 2 === 0 },
        behavior: { latencyMs: 5, errorRate: 0, responseBytes: 512 },
      });
    }
    await writeFile(
      join(outDir, "tools", `${id}.json`),
      JSON.stringify({ serverId: id, tools }, null, 2) + "\n",
    );
  }

  const config = {
    autoApproveAtOrAbove: "trusted",
    autoDiscover: false,
    servers: serverIds.map((id) => ({
      id,
      displayName: `Fixture ${id}`,
      trust: "trusted",
      enabled: true,
      transport: {
        type: "stdio",
        command: "node",
        args: [
          join(repoRoot, "stress", "external", "fixture-server.mjs"),
          "--manifest",
          join(outDir, "tools", `${id}.json`),
        ],
      },
    })),
  };
  await writeFile(join(outDir, "servers.json"), JSON.stringify(config, null, 2) + "\n");

  const home = join(outDir, "home");
  // Full isolation list per /tmp/action-hub-stress/ISOLATION.md (rev 21:27Z).
  // File-shaped vars (CACHE, CREDENTIALS, CONFIG, CONTROL) get file paths.
  const envSh = `# Generated by stress/external/make-fixture.mjs — source before every run.
export HOME="${home}"
export USERPROFILE="${home}"
export APPDATA="${outDir}/appdata"
export LOCALAPPDATA="${outDir}/localappdata"
export XDG_CACHE_HOME="${outDir}/cache"
export XDG_CONFIG_HOME="${outDir}/config"
export XDG_STATE_HOME="${outDir}/state"
export XDG_DATA_HOME="${outDir}/data"
export ACTION_HUB_CACHE="${outDir}/cache/action-hub.json"
export ACTION_HUB_CONFIG="${outDir}/servers.json"
export TMPDIR="${outDir}/tmp"
export TMP="${outDir}/tmp"
export TEMP="${outDir}/tmp"
export ACTION_HUB_SKILLS_DIR="${outDir}/skills"
export ACTION_HUB_DAEMON_DIR="${outDir}/daemon"
export ACTION_HUB_CREDENTIALS="${outDir}/credentials.json"
export ACTION_HUB_CONTROL="${outDir}/control.json"
export PI_CODING_AGENT_DIR="${outDir}/pi"
export CODEX_HOME="${outDir}/codex"
export CLAUDE_CONFIG_DIR="${outDir}/claude"
`;
  await writeFile(join(outDir, "env.sh"), envSh);

  // Pools for k6 and other drivers, derived from the actual manifests —
  // never hard-code action ids elsewhere.
  const first = serverIds[0];
  const firstTools = JSON.parse(await readFile(join(outDir, "tools", `${first}.json`), "utf8")).tools;
  await writeFile(
    join(outDir, "actions.json"),
    JSON.stringify(firstTools.slice(0, 20).map((t) => `${first}:${t.name}`), null, 2) + "\n",
  );
  // Distinct query per tool: the goal clause after the first colon (which
  // contains the varying verb + domain + index), prefixed with the tool name.
  const queries = firstTools.slice(0, 20).map((t) => {
    const clause = t.description.split(":").slice(1).join(":").replace(/\.\s*$/, "").trim();
    return `${t.name}: ${clause}`;
  });
  const unique = new Set(queries);
  if (unique.size < 4) {
    throw new Error(`query pool not distinct enough (${unique.size}/${queries.length})`);
  }
  await writeFile(join(outDir, "queries.json"), JSON.stringify([...unique], null, 2) + "\n");

  // Stable pointer for tools that default to ../.generated/external/*.json.
  for (const name of ["actions.json", "queries.json", "servers.json"]) {
    const link = join(outBase, name);
    try { await unlink(link); } catch { /* first run */ }
    await symlink(join(outDir, name), link);
  }

  const summary = {
    script: "make-fixture.mjs",
    ok: true,
    runStamp,
    servers: serverCount,
    toolsPerServer: toolsPer,
    totalTools: serverCount * toolsPer,
    outDir,
    queryPoolSize: unique.size,
    at: new Date().toISOString(),
  };
  await mkdir(resultsDir, { recursive: true });
  try {
    await writeFile(join(resultsDir, "external-make-fixture.json"), JSON.stringify(summary, null, 2) + "\n");
  } catch (writeCause) {
    // Contract: a run that cannot persist its artifact is not green.
    summary.ok = false;
    summary.artifactError = String(writeCause).slice(0, 200);
  }
  console.log(JSON.stringify(summary));
  if (summary.ok !== true) process.exit(1);
}

main().catch((cause) => {
  // Failure contract: one compact JSON last line with ok:false, exit nonzero.
  const summary = {
    script: "make-fixture.mjs",
    ok: false,
    error: String(cause?.stack ?? cause).slice(-2000),
    at: new Date().toISOString(),
  };
  console.log(JSON.stringify(summary));
  process.exit(1);
});
